<script setup>
import {toRefs,ref,onMounted,nextTick} from 'vue'
import {ElDrawer,ElTooltip,ElMessage} from 'element-plus'
import {IconHistory} from '@tabler/icons-vue'
import {mediaParserState} from '../state/media-parser.js'
import AppCard from '../components/AppCard.vue'
import ParseResult from '../components/ParseResult.vue'
import ParseHistory from '../components/ParseHistory.vue'
import '../css/parse-history.css'
const {input,quality,busy,result,error}=toRefs(mediaParserState)
const records=ref([]),historyLoading=ref(false),selected=ref(null),historyVisible=ref(true),drawer=ref(false),expired=ref(false),opening=ref(false)
const workspace=ref(null)
async function toggleHistory(){if(matchMedia('(max-width:850px)').matches){drawer.value=true;return}const area=workspace.value?.querySelector('.parser-results-area'),before=area?.getBoundingClientRect();historyVisible.value=!historyVisible.value;await nextTick();if(before&&!matchMedia('(prefers-reduced-motion:reduce)').matches){const after=area.getBoundingClientRect(),style=getComputedStyle(document.documentElement);area.animate([{transform:`translateX(${before.x-after.x}px)`,opacity:.65},{transform:'none',opacity:1}],{duration:parseFloat(style.getPropertyValue('--duration')),easing:style.getPropertyValue('--ease').trim()})}}
async function api(url,options){const r=await fetch(url,options),data=await r.json();if(!r.ok)throw Error(data.error||'操作失败');return data}
async function loadHistory(){historyLoading.value=true;try{records.value=await api('/api/parse-history')}catch(e){ElMessage.error(e.message)}finally{historyLoading.value=false}}
async function openHistory(id){if(busy.value||opening.value)return;opening.value=true;try{const saved=await api('/api/parse-history/'+id);result.value=saved.data;input.value=saved.data.url;quality.value=saved.quality;expired.value=saved.expired;selected.value=id;error.value='';drawer.value=false}catch(e){ElMessage.error(e.message)}finally{opening.value=false}}
async function removeHistory(id){try{await api('/api/parse-history'+(id?'/'+id:''),{method:'DELETE'});if(!id||selected.value===id)selected.value=null;await loadHistory()}catch(e){ElMessage.error(e.message)}}
async function parse(){if(busy.value||opening.value||!input.value.trim())return;busy.value=true;error.value='';result.value=null;expired.value=false;try{const data=await api('/api/parse',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({input:input.value,quality:'standard'})});result.value=data;selected.value=data.history_id;await loadHistory()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(loadHistory)
</script>
<template><div class="parser-page"><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="page-alert"/><AppCard class="parser-input parser-compact"><ElTooltip content="解析历史" :show-after="200"><button class="parser-history-toggle" aria-label="切换解析历史" :aria-expanded="historyVisible" @click="toggleHistory"><IconHistory :size="19"/></button></ElTooltip><el-input v-model="input" aria-label="作品分享内容" placeholder="粘贴抖音、小红书、B站、快手、TikTok、YouTube 或 X 链接" clearable @keydown.enter="parse"/><el-button type="primary" class="parse-button" :disabled="!input.trim()" :loading="busy" @click="parse">{{busy?'正在解析':'开始解析'}}</el-button></AppCard><div ref="workspace" class="parser-workspace" :class="{'history-collapsed':!historyVisible}"><aside v-show="historyVisible" class="parser-history-sidebar"><ParseHistory :items="records" :selected="selected" :loading="historyLoading" :disabled="busy||opening" @open="openHistory" @remove="removeHistory" @clear="removeHistory()" @refresh="loadHistory" @close="toggleHistory"/></aside><section class="parser-results-area" :aria-busy="busy||opening"><div v-if="expired" class="history-expired"><span>素材缓存已过期，重新解析后可预览和下载。</span><el-button type="primary" :loading="busy" @click="parse">重新解析</el-button></div><ParseResult v-if="result" :result="result"/><div v-else class="parser-empty"><IconHistory :size="30"/><span>{{busy?'正在获取作品素材…':'粘贴链接开始解析，或选择一条历史记录'}}</span></div></section></div><ElDrawer v-model="drawer" title="解析历史" aria-label="解析历史" :with-header="false" size="min(340px,90vw)" direction="ltr" class="history-mobile-drawer"><ParseHistory :items="records" :selected="selected" :loading="historyLoading" :disabled="busy||opening" @open="openHistory" @remove="removeHistory" @clear="removeHistory()" @refresh="loadHistory" @close="drawer=false"/></ElDrawer></div></template>
